-- Phase A: additive item-aware infrastructure. Legacy claim eligibility remains unchanged.
create table public.designer_request_items (id uuid primary key default gen_random_uuid(),request_id uuid not null references public.designer_requests(id) on delete cascade,item_type text not null check(item_type in ('banner','standee','poster','setup','other')),item_name text,content text,special_content text,style text,color text,specification text,sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint designer_request_items_other_name_check check(item_type<>'other' or nullif(btrim(coalesce(item_name,'')),'') is not null));
create index designer_request_items_request_sort_idx on public.designer_request_items(request_id,sort_order,created_at);
create trigger set_designer_request_items_updated_at before update on public.designer_request_items for each row execute function public.set_updated_at();
alter table public.designer_request_items enable row level security;
create policy "Designer request item readers are workflow participants" on public.designer_request_items for select to authenticated using(public.can_access_designer_request(request_id));
alter table public.designer_request_stages add column request_item_id uuid references public.designer_request_items(id) on delete cascade;
alter table public.designer_request_stages drop constraint designer_request_stages_request_id_stage_type_key;
create unique index designer_request_stages_legacy_type_unique on public.designer_request_stages(request_id,stage_type) where request_item_id is null;
create unique index designer_request_stages_item_type_unique on public.designer_request_stages(request_item_id,stage_type) where request_item_id is not null;
create function public.validate_designer_request_stage_item() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.request_item_id is not null and not exists(select 1 from public.designer_request_items i where i.id=new.request_item_id and i.request_id=new.request_id) then raise exception 'Stage item must belong to its request.'; end if; if new.request_item_id is null and exists(select 1 from public.designer_request_items i where i.request_id=new.request_id) then raise exception 'Item-aware request stages require request_item_id.'; end if; return new; end $$;
create trigger validate_designer_request_stage_item before insert or update of request_id,request_item_id on public.designer_request_stages for each row execute function public.validate_designer_request_stage_item();
drop policy if exists "Legacy design request updates only" on public.designer_requests;
create policy "Legacy design request updates only" on public.designer_requests for update to authenticated using(work_mode is null and not exists(select 1 from public.designer_request_items i where i.request_id=designer_requests.id) and (agent_profile_id=auth.uid() or designer_profile_id=auth.uid())) with check(work_mode is null and not exists(select 1 from public.designer_request_items i where i.request_id=designer_requests.id) and (agent_profile_id=auth.uid() or designer_profile_id=auth.uid()));
insert into public.permission_items(permission_key,parent_key,name,sort_order,is_reserved) values ('designer-design-eligible',null,'美工设计阶段资格',33,false),('designer-production-eligible',null,'美工制作阶段资格',34,false),('designer-setup-eligible',null,'美工布置阶段资格',35,false) on conflict(permission_key) do update set parent_key=excluded.parent_key,name=excluded.name,sort_order=excluded.sort_order,is_reserved=excluded.is_reserved;
create function public.complete_item_aware_designer_request_if_ready(p_request_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare request_status public.design_request_status; begin select status into request_status from public.designer_requests where id=p_request_id for update; if request_status is null or request_status in ('completed','cancelled') then return; end if; if exists(select 1 from public.designer_request_items where request_id=p_request_id) and not exists(select 1 from public.designer_request_stages where request_id=p_request_id and status<>'completed') then update public.designer_requests set status='completed',completed_at=now() where id=p_request_id and status not in ('completed','cancelled'); end if; end $$;
create function public.create_designer_request_with_items(p_creator_profile_id uuid,p_task_type text,p_event_start_at timestamptz,p_event_end_at timestamptz,p_live_room text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare c public.creator_profiles; rid uuid; eid uuid; item jsonb; stage_name text; iid uuid; item_type_value text; item_name_value text; stage_count integer; distinct_stage_count integer; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.current_user_has_permission('agent-design-requests','use') then raise exception 'Permission denied'; end if; if p_task_type is null or p_task_type not in ('daily','activity') then raise exception 'Invalid task type'; end if; if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one item is required'; end if; select * into c from public.creator_profiles where id=p_creator_profile_id and status='active'; if c.id is null or not public.current_user_can_access_region(c.region_id) then raise exception 'Creator access denied'; end if; select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1; insert into public.designer_requests(agent_profile_id,agent_employee_id,creator_profile_id,creator_entity_id,region_id,request_type,task_type,platform,platform_user_id,creator_name,platform_account,event_start_at,event_end_at,live_room) values(auth.uid(),eid,c.id,c.creator_entity_id,c.region_id,'special',p_task_type,c.platform,c.platform_user_id,c.creator_name,c.platform_account,p_event_start_at,p_event_end_at,nullif(btrim(coalesce(p_live_room,'')),'')) returning id into rid; for item in select value from jsonb_array_elements(p_items) loop item_type_value:=item->>'item_type';item_name_value:=nullif(btrim(coalesce(item->>'item_name','')),''); if jsonb_typeof(item)<>'object' or item_type_value not in ('banner','standee','poster','setup','other') or (item_type_value='other' and item_name_value is null) then raise exception 'Invalid item'; end if; if jsonb_typeof(item->'stages')<>'array' or jsonb_array_length(item->'stages')=0 then raise exception 'Each item needs at least one stage'; end if; select count(*),count(distinct value) into stage_count,distinct_stage_count from jsonb_array_elements_text(item->'stages'); if stage_count<>jsonb_array_length(item->'stages') or stage_count<>distinct_stage_count or exists(select 1 from jsonb_array_elements_text(item->'stages') s(value) where s.value not in ('design','production','setup')) then raise exception 'Invalid or duplicate item stage'; end if; insert into public.designer_request_items(request_id,item_type,item_name,content,special_content,style,color,specification,sort_order) values(rid,item_type_value,item_name_value,nullif(btrim(coalesce(item->>'content','')),''),nullif(btrim(coalesce(item->>'special_content','')),''),nullif(btrim(coalesce(item->>'style','')),''),nullif(btrim(coalesce(item->>'color','')),''),nullif(btrim(coalesce(item->>'specification','')),''),coalesce((item->>'sort_order')::integer,0)) returning id into iid; for stage_name in select value from jsonb_array_elements_text(item->'stages') loop insert into public.designer_request_stages(request_id,request_item_id,stage_type,status) values(rid,iid,stage_name::public.designer_stage_type,case when stage_name='production' and (item->'stages')?'design' then 'scheduled'::public.designer_stage_status else 'unclaimed'::public.designer_stage_status end); end loop; end loop; return rid; end $$;
create or replace function public.claim_designer_request_stage(p_stage_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages;r public.designer_requests;eid uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into s from public.designer_request_stages where id=p_stage_id; select * into r from public.designer_requests where id=s.request_id for update; select * into s from public.designer_request_stages where id=p_stage_id for update; if r.status in ('completed','cancelled') or s.status<>'unclaimed' or not public.current_user_has_permission('designer-intake','use') or not public.can_access_designer_request(s.request_id) then raise exception 'Stage unavailable'; end if; select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1; if eid is null then raise exception 'Active employee required'; end if; update public.designer_request_stages set status=(case when s.stage_type='setup' then 'scheduled' else 'in_progress' end)::public.designer_stage_status,assignee_profile_id=auth.uid(),assignee_employee_id=eid,accepted_at=now() where id=s.id; end $$;
create or replace function public.confirm_designer_request_stage(p_stage_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages;r public.designer_requests;eid uuid;item_aware boolean; begin if auth.uid() is null then raise exception 'Authentication required'; end if;select * into s from public.designer_request_stages where id=p_stage_id;select * into r from public.designer_requests where id=s.request_id for update;select * into s from public.designer_request_stages where id=p_stage_id for update;if r.status in ('completed','cancelled') or r.agent_profile_id<>auth.uid() or s.status<>'awaiting_agent_confirmation' then raise exception 'Confirmation denied';end if;select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1;update public.designer_request_stages set status='completed',confirmed_at=now(),confirmed_by_profile_id=auth.uid(),confirmed_by_employee_id=eid where id=s.id;item_aware:=exists(select 1 from public.designer_request_items where request_id=r.id);if s.stage_type='design' and ((item_aware and s.request_item_id is not null) or (not item_aware and r.work_mode='design_production')) then update public.designer_request_stages set status='unclaimed' where request_id=r.id and stage_type='production' and status='scheduled' and (not item_aware or request_item_id=s.request_item_id);end if;if item_aware then perform public.complete_item_aware_designer_request_if_ready(r.id);elsif not(s.stage_type='design' and r.work_mode='design_production') then update public.designer_requests set status='completed',completed_at=now() where id=r.id;end if;end $$;
create or replace function public.advance_designer_request_stage(p_stage_id uuid,p_action text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages;r public.designer_requests;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into s from public.designer_request_stages where id=p_stage_id;select * into r from public.designer_requests where id=s.request_id for update;select * into s from public.designer_request_stages where id=p_stage_id for update;if r.status in ('completed','cancelled') or s.assignee_profile_id<>auth.uid() or s.stage_type<>'setup' then raise exception 'Permission denied';end if;if p_action='arrange' and s.status='scheduled' then update public.designer_request_stages set status='arranged' where id=s.id;elsif p_action='start' and s.status='arranged' then update public.designer_request_stages set status='in_progress' where id=s.id;else raise exception 'Invalid transition';end if;end $$;
create or replace function public.submit_designer_request_stage(p_stage_id uuid,p_feedback text default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages;r public.designer_requests;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into s from public.designer_request_stages where id=p_stage_id;select * into r from public.designer_requests where id=s.request_id for update;select * into s from public.designer_request_stages where id=p_stage_id for update;if r.status in ('completed','cancelled') or s.assignee_profile_id<>auth.uid() or s.status not in ('in_progress','revision') then raise exception 'Invalid submission';end if;update public.designer_request_stages set status='awaiting_agent_confirmation',submitted_at=now(),feedback=coalesce(nullif(btrim(p_feedback),''),feedback) where id=s.id;end $$;
create or replace function public.return_designer_request_stage(p_stage_id uuid,p_feedback text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages;r public.designer_requests;begin if auth.uid() is null then raise exception 'Authentication required';end if;if nullif(btrim(p_feedback),'') is null then raise exception 'Feedback is required';end if;select * into s from public.designer_request_stages where id=p_stage_id;select * into r from public.designer_requests where id=s.request_id for update;select * into s from public.designer_request_stages where id=p_stage_id for update;if r.status in ('completed','cancelled') or r.agent_profile_id<>auth.uid() or s.status<>'awaiting_agent_confirmation' then raise exception 'Return denied';end if;update public.designer_request_stages set status='revision',feedback=btrim(p_feedback),feedback_count=feedback_count+1 where id=s.id;end $$;
revoke all on function public.complete_item_aware_designer_request_if_ready(uuid),public.create_designer_request_with_items(uuid,text,timestamptz,timestamptz,text,jsonb) from public,anon;grant execute on function public.create_designer_request_with_items(uuid,text,timestamptz,timestamptz,text,jsonb) to authenticated;
